export function clipRange(start,end,duration){if(!Number.isFinite(duration)||duration<=0)return 'This video has no readable duration. Upload a standard MP4 or a video with duration metadata.';if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end>duration||end<=start)return 'Choose a start and end within the video, with end after start.';if(end-start>180)return 'Each clip can be up to three minutes. Choose a shorter range.';return '';}
export function clipDimensions(width,height){const scale=Math.min(1,1280/width,1280/height);return [Math.max(2,Math.floor(width*scale/2)*2),Math.max(2,Math.floor(height*scale/2)*2)];}
